/**
 * BE03c 1298-1302: "A response with an unmapped status or a message not generated by its
 * operation catalog is a contract failure and is treated as INTERNAL_ERROR 500 without leaking
 * the original payload." A PostgREST or PostgreSQL fault answered with a 4xx is not the caller's
 * refusal, whatever its HTTP status: every 03c production adapter scrubs it to 500, never to the
 * 401/403/404/409/422 the status alone would suggest and never to a retryable 503.
 */
export const PROVIDER_FAULTS: readonly (readonly [string, number, unknown])[] =
  [
    [
      'PGRST202 function not found (RPC missing or unexposed)',
      404,
      {
        code: 'PGRST202',
        message: 'Could not find the function platform_api.x',
      },
    ],
    [
      'PGRST301 bad service credential',
      401,
      { code: 'PGRST301', message: 'JWT expired' },
    ],
    [
      'SQLSTATE 42702 ambiguous column',
      400,
      { code: '42702', message: 'column reference "actor_id" is ambiguous' },
    ],
    ['SQLSTATE 23505 unique violation', 409, { code: '23505', message: 'x' }],
    [
      'SQLSTATE 40001 engine serialization failure',
      409,
      { code: '40001', message: 'could not serialize access' },
    ],
    ['SQLSTATE 42501 insufficient privilege', 403, { code: '42501' }],
    ['PGRST116 row count', 422, { code: 'PGRST116', message: 'x' }],
    ['provider rate limit without a token', 429, { message: 'slow down' }],
    ['payload without any code', 404, { message: 'NOT_FOUND' }],
    ['empty object', 404, {}],
    ['numeric code', 400, { code: 42702, message: 'x' }],
    ['unsupported 4xx status', 418, { code: 'PGRST999' }],
    ['array payload', 400, ['NOT_FOUND']],
    ['string payload', 404, 'NOT_FOUND'],
    ['null payload', 400, null],
  ];
